const tools = [
  {
    name: 'users_get_many',
    description: 'Look up multiple users by ID',
    inputSchema: {
      type: 'object',
      properties: {
        user_ids: {
          type: 'array',
          items: { type: 'string' },
          minItems: 1,
          maxItems: 5,
          uniqueItems: true,
        },
      },
      required: ['user_ids'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return tools;
}

export async function callTool(name, args) {
  const tool = tools.find(t => t.name === name);
  if (!tool) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (name === 'users_get_many') {
    // Validate args
    if (typeof args !== 'object' || args === null) {
      throw new Error('Invalid arguments');
    }

    const { user_ids } = args;

    // Check for extra fields
    const allowedKeys = ['user_ids'];
    const actualKeys = Object.keys(args);
    for (const key of actualKeys) {
      if (!allowedKeys.includes(key)) {
        throw new Error(`Unexpected field: ${key}`);
      }
    }

    // Validate user_ids
    if (!Array.isArray(user_ids)) {
      throw new Error('user_ids must be an array');
    }
    if (user_ids.length === 0) {
      throw new Error('user_ids must not be empty');
    }
    if (user_ids.length > 5) {
      throw new Error('user_ids must have at most 5 entries');
    }

    // Check all entries are strings
    for (let i = 0; i < user_ids.length; i++) {
      if (typeof user_ids[i] !== 'string') {
        throw new Error(`user_ids[${i}] must be a string`);
      }
    }

    // Check for duplicates
    const seen = new Set();
    for (const id of user_ids) {
      if (seen.has(id)) {
        throw new Error(`Duplicate user_id: ${id}`);
      }
      seen.add(id);
    }

    // Build result: one line per requested id
    const lines = user_ids.map(id => {
      if (users[id] !== undefined) {
        return `${id}: ${users[id].name}`;
      } else {
        return `${id}: (not found)`;
      }
    });

    return {
      content: [
        {
          type: 'text',
          text: lines.join('\n'),
        },
      ],
    };
  }

  throw new Error(`Unknown tool: ${name}`);
}
